huggingface_raw_latex:
\begin{definition} Recall that a partially ordered set (a \emph{poset}) is a set $P$ with a relation $\preceq$ that is reflexive, antisymmetric, and
 transitive. Following \cite{stanleythesis} (see also \cite[Chapter 3]{Stanley}), we define an \emph{$\omega$-labeling} of a poset with $n$ elements as a bijection $\omega : P \rightarrow [n]$, and the \emph{order polynomial} $\Omega _{P,\omega}(k)$ as
 \[  \Omega _{P,\omega} (k) := \# \left\{ (x_1, x_2, ... , x_n) \in [k]^n : \begin{array}{l} x_u \leq x_v \text{ if } u \preceq v \text{ and } \omega (u) < \omega (v) \\ x_u < x_v \text{ if } u \preceq v \text{ and } \omega (u) > \omega (v) \end{array} \right\} . \] (Here $\# S$ denotes the cardinality of the set $S$. ) \end{definition}

anthropic_raw_latex:
\begin{defn}
A \emph{binary phylogenetic tree}, $T=(V,E,\varphi)$ on a finite set of taxa $X$, is a triple consisting of a finite set of vertices, V , a set $E$ of edges between vertices, and a "labeling" map $\varphi : X \rightarrow L$, where $L \subset V$ contains all vertices of degree one or \emph{leaves}, such that the graph $(V,E)$ is an unrooted binary tree and
the map $\varphi$ induces a bijection between $X$ and the set $L$ of leaves of $T$.
\end{defn}

openai_raw_latex:
\begin{defn}
A \emph{binary phylogenetic tree}, $T=(V,E,\varphi)$ on a finite set of taxa $X$, is a triple consisting of a finite set of vertices, V , a set $E$ of edges between vertices, and a "labeling" map $\varphi : X \rightarrow L$, where $L \subset V$ contains all vertices of degree one or \emph{leaves}, such that the graph $(V,E)$ is an unrooted binary tree and
the map $\varphi$ induces a bijection between $X$ and the set $L$ of leaves of $T$.
\end{defn}

\begin{defn}
Phylogenetic trees, $T_1=(V_1, E_1, \varphi_1)$ and  $T_2=(V_2, E_2, \varphi_2)$ on a taxon set $X$, are \emph{isomorphic} if there exists a bijective map $f : V_1 \rightarrow V_2$, called an \emph{isomorphism}, such that if $\{u,v\} \in E_1$ then $\{f (u), f (v)\} \in E_2$ and  for every  $x \in X$ we have $\varphi_2 (x)=f (\varphi_1 (x))$ . 
\end{defn}

