\end{defn}

openai_raw_latex:
\begin{defn} (\protect\cite{steel})
A system of quartet trees, $Q$, is \emph{definitive}, if up to isomorphism, there exists a unique binary phylogenetic tree $T$ for which $Q \subseteq Q_T$. 
\end{defn}

anthropic_raw_latex:
\begin{defn}
(\cite{semple}) Let $T = (V,E,\varphi)$ be a binary phylogenetic tree and let $ab|cd \in Q_T$. An interior edge $e$ of $T$ is \emph{distinguished} by $ab|cd$ if $e$ is the only edge that separates $a$ and $b$ from $c$ and $d$.  
\end{defn}

manual_raw_latex:
For a compatible system of $n-3$ quartet trees $Q$ on a taxon set $X$, define the associated graph $G_T(Q)$ with vertex set $V$ and edge set $E$ as follows:
\begin{itemize}
\item The vertex set $V$ is the set of all quartet trees $q \in Q$ which distinguish a unique edge in $T$. 
\item Vertex pairs $\{q_i,q_j\}$ are connected by an edge $e \in E$ if the edge $e_i$ that $q_i$ distinguishes is adjacent to the edge $e_j$ that $q_j$ distinguishes and $|supp(\{q_i,q_j\})|=5$.
\end{itemize}
\label{order}

